CREATE VIEW v182674 AS SELECT CONCAT(SHA2(RAND(), 0), SHA2(RAND(), 0)), CONCAT(COALESCE(MIN(DATE_FORMAT(NOW(), '%Y-%m-%d')), ' ull')), CONCAT(REGEXP_REPLACE('aaa', 'a', 'X'), 'x'), CONCAT(COALESCE(x1.v182195, x1.v182195)), CONCAT(':', TRIM(LEADING '.*' FROM '.*my'), ':', TRIM(TRAILING '.*' FROM 'sql.*.*'), ':'), CONCAT(CURRENT_TIMESTAMP()) FROM v182193 AS x1